class Counter {                              // guardian: owns lock + state
    mutable std::mutex mutex_;               // private, one per object
    int total_ = 0, hits_ = 0;
public:
    void add(int delta) {
        std::scoped_lock lock{mutex_};       // named: lives for the scope
        total_ += delta; hits_ += 1;         // invariant spans both fields
    }
    std::pair<int, int> snapshot() const {
        std::scoped_lock lock{mutex_}; return {total_, hits_};   // copy out
    }
};
